CREATE TABLE payments (id UUID PRIMARY KEY, order_id UUID NOT NULL, idempotency_key VARCHAR(255) UNIQUE NOT NULL, amount NUMERIC(19,2) NOT NULL, status VARCHAR(32) NOT NULL, provider_reference VARCHAR(255), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE payment_refunds (id UUID PRIMARY KEY, payment_id UUID NOT NULL REFERENCES payments(id), amount NUMERIC(19,2) NOT NULL, status VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE outbox (id UUID PRIMARY KEY, aggregate_id UUID NOT NULL, event_type VARCHAR(100) NOT NULL, payload TEXT NOT NULL, published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT now());
